insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('prms', 'beginner', 'module', 'm01-the-resources-framework', 1, 'The framework asks two separate questions of every quantity. Which pair of answers does a complete figure carry?', '["A licence and a gazette date, which tell a reader which Nigerian regulator accepted the figure for booking.", "A Pg and a Pd, which multiplied together give the class of the project.", "A class, which describes the project, and a category, which places the estimate in the range of outcomes.", "A discovery status and a unit, which together decide whether the figure is 1P, 2P or 3P in the table."]'::jsonb, 2, 'The class answers the question about the project (is it discovered, can it be recovered, is it commercial; PRMS 2.1 and Table 1). The category answers the question about the estimate (the low, best or high outcome; PRMS 2.2.2.2). The two chances give a chance of commerciality, which sits beside the class and sets none of it. A discovery status and a unit set no category, and no Nigerian booking rule was found at all.'),
  ('prms', 'beginner', 'module', 'm01-the-resources-framework', 2, 'How many of the eight Ekene projects does the engine classify as Contingent Resources on their stated facts?', '["Three: EKN-3, EKN-4 and EKN-5.", "Two: EKN-1 and EKN-2.", "Five, EKN-8 included.", "Two: EKN-6 and EKN-7, the prospect and the lead that still wait on a well."]'::jsonb, 0, 'The engine returns Contingent Resources for Ekene East gas, Ekene North appraisal and Ekene West tight sand. EKN-1 and EKN-2 are Reserves. EKN-6 and EKN-7 are undiscovered, so they are Prospective Resources. EKN-8 is discovered but has no recovery project, so it is Discovered Unrecoverable and does not reach the commerciality test.'),
  ('prms', 'beginner', 'module', 'm01-the-resources-framework', 3, 'SPE-PRMS 2018 (June 2018; CC BY-NC-ND 4.0) is cited throughout this course by section number, and none of its sentences appears. What is the reason?', '["The standard is out of date, and the course cites only the sections that the 2022 errata did not replace.", "Its licence allows no commercial use and no derived works, and this course is sold.", "Its sentences are long, so the course shortens each one and prints the shortened version in quotation marks.", "Quoting it would need the permission of the Commission, which reviews every text the course uses."]'::jsonb, 1, 'The licence is non-commercial and no-derivatives, and a paid course is commercial, so the course teaches each idea in its own words and gives the section it comes from. The errata were checked and change none of the sections the engine applies. A shortened sentence in quotation marks is still a quotation. The Commission plays no part in the licence of an SPE text.'),
  ('prms', 'beginner', 'module', 'm01-the-resources-framework', 4, 'On what date was every text in the course''s table of sources read?', '["2026-09-01, the date of the eCFR version the course read.", "27 August 2021, the Act''s gazette date.", "1 April 2026, the date of the Commission''s release on the national reserves position.", "2026-09-27, the same date against every row."]'::jsonb, 3, 'Every text in the table was read on 2026-09-27. The eCFR version current at 2026-09-01 is the edition of the US rules, 27 August 2021 is the gazette date of the Act, and 1 April 2026 is the date of the NUPRC release. Each of those is an edition or publication date, and none is the date the course read a text.'),
  ('prms', 'beginner', 'module', 'm01-the-resources-framework', 5, 'How does the course use the Guidelines for Application of the PRMS?', '["It cites the November 2011 edition for its printed figures and section numbers, and quotes none of its prose.", "It quotes the 2022 edition with its citation, since that edition replaced the one from 2011 and is the current text.", "It quotes the 2011 edition word for word, because a superseded edition carries no copyright.", "It leaves the Guidelines out of the course entirely, because no open licence is printed on them."]'::jsonb, 0, 'The 2011 edition prints no licence and is treated as copyright, so the course takes only its figures and section numbers. The 2022 edition is sold and was not read, so the course names the edition it did read by its year. A superseded edition keeps its copyright, and the course does use the 2011 figures, with their section numbers.'),
  ('prms', 'beginner', 'module', 'm01-the-resources-framework', 6, 'Which of these texts does the course quote word for word, with its citation?', '["The PRMS Frequently Asked Questions (November 2022), whose answers the course prints with their numbers.", "NUPRC''s release of 1 April 2026, quoted beside its gas figures.", "17 CFR 229.1202 and 229.1203, the US federal rules in the eCFR version current at 2026-09-01.", "The Nigerian Upstream Petroleum (Commercial) Regulations, 2025, from which the course prints reg. 6 in full."]'::jsonb, 2, 'The US federal text is public domain, so the course quotes it with its citation, as it does the Act and S.I. No. 37 of 2023. The FAQs are copyright SPE with all rights reserved, so only their figures and answer numbers are used. The release''s page reads all rights reserved, so only its figures and date are cited. The Commercial Regulations are used by concept only.'),
  ('prms', 'beginner', 'module', 'm01-the-resources-framework', 7, 'What does the Ekene fixture file state about itself in the statement that opens it?', '["That it is a cut of real Niger Delta data, with the names changed so the operator cannot be identified.", "That it is SYNTHETIC teaching data, and that no real company, field, licence, price, cost, reserves figure or regulator decision is in it.", "That its eight projects were classified by the Commission, and the course reproduces the Commission''s classes.", "That its figures are the rates of the Petroleum Industry Act 2021, rounded for teaching purposes."]'::jsonb, 1, 'The file opens by calling itself SYNTHETIC teaching data for the Ekene field and listing what it does not contain. Its classes are what the engine returns on the stated facts, checked against the file''s own notes. No regulator decision appears in it, and its royalty, tax and prices are synthetic teaching figures, which are not the rates of the Act.'),
  ('prms', 'beginner', 'module', 'm01-the-resources-framework', 8, 'The engine''s `classify` function is called on a field with several projects. What does one call classify?', '["The whole field, which receives the class of its most mature project and carries it for every project.", "The accumulation, so all projects on Ekene Main share the class of the waterflood.", "Every project in the box at once, as one field class.", "One project: one set of stated facts gives one class and one sub-class."]'::jsonb, 3, 'The project is the unit. Each classify call takes one project''s stated facts and returns one class, so Ekene carries eight classifications. Nothing in the engine adds them into a field class, and the same accumulation holds Reserves in EKN-1 and Discovered Unrecoverable in EKN-8, because each project is read on its own facts.'),
  ('prms', 'beginner', 'module', 'm01-the-resources-framework', 9, 'EKN-8, Ekene Main residual oil, is discovered and its stated recovery project is none. At which step of the engine''s decision list does its classification stop?', '["At the second step, the recovery project: it becomes Discovered Unrecoverable and nothing further is read.", "At the first step, discovery, because residual oil is left in the rock and is treated as undiscovered.", "At the fourth step, the commerciality test, where it fails the criterion on facilities and on the market.", "At the third step, where every project without a sub-class is sent to the Prospective Resources class."]'::jsonb, 0, 'The list runs discovery, then a recovery project, then the undiscovered branch, then the commerciality test (PRMS 2.1.1.1, 2.1.0.1, 2.1.1.2, 2.1.2.1). EKN-8 is discovered, so it passes the first step, and with no recovery project it is Discovered Unrecoverable at the second, before any commerciality test. The third step applies only to undiscovered projects.'),
  ('prms', 'beginner', 'module', 'm01-the-resources-framework', 10, 'A learner clears the Discovery control on Ekene Main waterflood and runs the box. Which message is printed?', '["A Reserves class, read from the criteria that are all met.", "discovery must be one of \"discovered\", \"undiscovered\"; got \"appraised\"", "discovery must be one of \"discovered\", \"undiscovered\"; got nothing", "A result with the class left blank and a warning."]'::jsonb, 2, 'Those are the engine''s own words: a discovery status has no default, so a missing one is refused by name, and the message ends "got nothing" because no value was given. The message that ends in "appraised" is the refusal of a status the engine does not accept. The engine does not guess a status from the other facts, and it returns no half-filled result.'),
  ('prms', 'beginner', 'module', 'm01-the-resources-framework', 11, 'A box carries an unknown top-level key, `maturity`, and also lacks its discovery status. Which problem does the engine name?', '["The missing discovery status, since a required input always comes first.", "The unknown key: every function checks its accepted keys before it reads any input.", "Both problems, listed in one message in the order they appear in the box.", "Neither: an unknown key is dropped silently and the class is returned with a warning."]'::jsonb, 1, 'The engine refuses on the unknown key first, in its own words: "maturity is not an accepted key; the accepted keys at the top level are name, discovery, recoveryProject, subClass, commerciality, economicStatus, projectStatus, reservesStatus, chances, nigeria". It names one field per refusal, and a misspelt or unknown key is refused by name, so nothing is dropped silently.'),
  ('prms', 'beginner', 'module', 'm01-the-resources-framework', 12, 'EKN-4 comes back as Contingent Resources with a list of criteria that are not met. How does the course describe that output?', '["As a refusal, since the project failed the test.", "As a warning, which the capstone treats as a refusal whenever a list is printed.", "As an error in the box, which the learner fixes by setting the missing criteria to true.", "As a result: the list is a finding about the project."]'::jsonb, 3, 'A result returned with a reason is a result. The unmet criteria describe the project and are printed with its class. A refusal returns no figures, and its message names an input the engine cannot read. Setting the criteria to true would change the stated facts of the project, which is a different project.'),
  ('prms', 'beginner', 'module', 'm01-the-resources-framework', 13, 'What is every graded number in this course?', '["A return value of the engine on fixed inputs, so the same inputs give the same number on any machine.", "A figure the tutor works out by hand from the lesson tables and types into the answer key.", "A Monte Carlo figure, graded within a tolerance wide enough to cover the scatter of the draws.", "A figure published by the Commission, which the course checks against the engine before grading."]'::jsonb, 0, 'Each graded figure is computed by one of the engine''s functions on inputs written down in advance, so there is exactly one right answer. No graded figure is a Monte Carlo draw. The Commission''s figures are cited as published and are never graded.'),
  ('prms', 'beginner', 'module', 'm01-the-resources-framework', 14, 'Which of these is outside what the engine does?', '["Naming each criterion that keeps a project out of Reserves.", "Building a production forecast from well rates.", "Labelling three stated estimates with their probabilities.", "Refusing an input key it does not read, at any level."]'::jsonb, 1, 'The engine builds no production forecast, no in-place volume and no distribution from data; a forecast from well rates belongs to the decline curve analysis course. Naming the blockers is part of classify, the categories are what categorize returns, and every call refuses an unknown key by name.'),
  ('prms', 'beginner', 'module', 'm01-the-resources-framework', 15, 'A report calls Nigeria''s published national 2P gas figure "Nigeria''s gas reserves". How does this course word that figure?', '["As Reserves in the class sense, summed over every licence.", "As Contingent Resources, since no project test was passed.", "As resources, the word for every quantity in the ground.", "As reported reserves, with its date and whoever reported it."]'::jsonb, 3, 'In this course reserves is the PRMS class: discovered, commercial and remaining. A national or company figure is written as reported reserves, with its date and who reported it, which for the national gas figure is the Commission''s release of 1 April 2026. Contingent Resources is a class of projects. Resources alone means all quantities together.'),
  ('prms', 'beginner', 'module', 'm02-discovered-and-undiscovered', 1, 'A team states the discovery status of its accumulation as "appraised". What does the engine return?', '["The class Contingent Resources, since appraisal means a plan is pending.", "A refusal naming `discovery`, since only \"discovered\" and \"undiscovered\" are accepted.", "A result that treats \"appraised\" as discovered and prints a note to say so.", "The class Prospective Resources, since appraisal comes before a development decision."]'::jsonb, 1, 'The engine''s own words are: discovery must be one of "discovered", "undiscovered"; got "appraised". It reads a stated status and checks it against the two it accepts; it maps no other word onto them. An appraised accumulation is a known one, so the team states "discovered", and the appraisal shows up in other facts such as a development plan.'),
  ('prms', 'beginner', 'module', 'm02-discovered-and-undiscovered', 2, 'An accumulation has not yet been found by a well, and a recovery project with established technology could apply to it. Which class does the engine return?', '["Contingent Resources, held back.", "Undiscovered Unrecoverable.", "Reserves at the undeveloped status.", "Prospective Resources."]'::jsonb, 3, 'Undiscovered with a recovery project is Prospective Resources (PRMS 2.1.0.1, Table 1), with a stated sub-class and stated chances. Contingent Resources are discovered. Undiscovered Unrecoverable needs the recovery project to be none. Reserves need a discovered project that meets every commerciality criterion.'),
  ('prms', 'beginner', 'module', 'm02-discovered-and-undiscovered', 3, 'Which Prospective sub-class does the Ekene file state for EKN-7, Ekene Shallow?', '["Lead: a potential accumulation that needs more data before it can become a prospect.", "Prospect: a potential accumulation that is defined well enough to be drilled.", "Play: a family of potential accumulations across a basin with shared geology.", "Development-pending, the sub-class the engine gives to every project still waiting on data."]'::jsonb, 0, 'EKN-7 is stated as a lead, and the engine''s decision reads "lead (stated)" with PRMS 2.1.3.5.9 and Table 1. EKN-6, Ekene Deep, is the prospect, and the course''s small case states a play. Development-pending is a Contingent sub-class, which the engine refuses on an undiscovered project.'),
  ('prms', 'beginner', 'module', 'm02-discovered-and-undiscovered', 4, 'Which description fits a play, in the course''s own words?', '["A single potential accumulation mapped well enough that a well could be drilled on it next season.", "A discovered accumulation that is waiting for the money and approvals it needs to be developed.", "A family of potential accumulations across a basin, sharing the geology that could trap petroleum.", "A known accumulation that no recovery project can reach with any technology available today."]'::jsonb, 2, 'A play is a family of such accumulations across a basin (PRMS 2.1.3.5.9, Table 1), the least mature of the three Prospective sub-classes. A single accumulation ready to drill is a prospect. A discovered one waiting on money and approvals is Contingent Resources, and a known one with no recovery project is Discovered Unrecoverable.'),
  ('prms', 'beginner', 'module', 'm02-discovered-and-undiscovered', 5, 'A learner gives the lead a Contingent sub-class, development-pending. Which message comes back?', '["subClass must be left out for unrecoverable quantities (no recovery project applies); got \"development-pending\"", "A result with the class changed to Contingent Resources, since the stated sub-class belongs there.", "subClass must be one of \"prospect\", \"lead\", \"play\"; got \"development-pending\"", "The lead''s result, with the sub-class reset to \"lead\"."]'::jsonb, 2, 'Those are the engine''s own words for the golden case class-refuse-prospective-subclass. An undiscovered project with a recovery project is Prospective Resources, and only the three Prospective sub-classes are accepted. The engine changes no class to fit a sub-class, replaces nothing it was given, and gives the unrecoverable message only when the recovery project is none.'),
  ('prms', 'beginner', 'module', 'm02-discovered-and-undiscovered', 6, 'Why does the engine refuse a commerciality block stated for an undiscovered accumulation?', '["The commerciality test applies to discovered quantities (PRMS 2.1.2).", "An undiscovered accumulation becomes Reserves once all seven criteria are true.", "The commerciality block may be stated only once the chance of development has reached 50 percent.", "The block is accepted until a criterion is false."]'::jsonb, 0, 'The engine refuses the block by name: commerciality must be left out for an undiscovered accumulation, citing PRMS 2.1.2. Nothing has been found yet to develop, so the class is Prospective Resources and the chances carry the uncertainty. No class is reached without its stated facts, and no chance threshold opens the test.'),
  ('prms', 'beginner', 'module', 'm02-discovered-and-undiscovered', 7, 'The oil left behind in Ekene Main, which no project can reach, is classified in the calculator. Which class comes back, with which sections cited?', '["Contingent Resources at development-not-viable, citing PRMS 2.1.3.5.6 and Table 1.", "Reserves at developed-non-producing, citing Table 2.", "Undiscovered Unrecoverable, citing PRMS 2.1.1.1.", "Discovered Unrecoverable, citing PRMS 2.1.0.1 and 2.1.1.2."]'::jsonb, 3, 'The engine''s reason reads, in its own words: recovery project: none applies with established technology or technology under development: Discovered Unrecoverable (PRMS 2.1.0.1, 2.1.1.2). A not-viable Contingent project still has a project. Reserves need every criterion met. EKN-8 is a known accumulation, so the undiscovered class cannot apply.'),
  ('prms', 'beginner', 'module', 'm02-discovered-and-undiscovered', 8, 'Which class does the engine return for an undiscovered accumulation stated with a recovery project of none?', '["Prospective Resources, sub-class play.", "Undiscovered Unrecoverable.", "Discovered Unrecoverable, as no project applies.", "A refusal naming the recovery project."]'::jsonb, 1, 'The golden input class-undiscovered-unrecoverable returns "Undiscovered Unrecoverable". With no recovery project the engine stops at the second step, whether the accumulation is discovered or undiscovered, so there are two unrecoverable classes. Prospective Resources need a recovery project, and a recovery project of none is a stated value the engine accepts.'),
  ('prms', 'beginner', 'module', 'm02-discovered-and-undiscovered', 9, 'Residual oil in Ekene Main is given the sub-class development-not-viable. How does the classify call respond?', '["subClass must be left out for unrecoverable quantities (no recovery project applies); got \"development-not-viable\"", "subClass must be one of \"prospect\", \"lead\", \"play\"; got \"development-not-viable\"", "Contingent Resources, sub-class development-not-viable (stated).", "Discovered Unrecoverable with the sub-class printed as stated."]'::jsonb, 0, 'Those are the engine''s own words: unrecoverable quantities have no project, so no sub-class describes one. Development-not-viable is a Contingent sub-class, for a project that exists and is not expected to go ahead. The Prospective list applies only to undiscovered projects with a recovery project, and the class of EKN-8 is set by its facts, which the stated sub-class does not change.'),
  ('prms', 'beginner', 'module', 'm02-discovered-and-undiscovered', 10, 'What does the engine return as the category labels of EKN-8, and what does its basis say?', '["The labels 1C, 2C and 3C, since discovered quantities without Reserves always fall into Contingent.", "No labels (null), and the basis reads \"none: unrecoverable quantities are not categorized\".", "1U, 2U and 3U, since quantities no project can reach are counted as undiscovered ones.", "The labels 1P, 2P and 3P at zero."]'::jsonb, 1, 'Unrecoverable quantities carry no categories: the engine returns labels null and gives its basis in its own words, none: unrecoverable quantities are not categorized. The C labels belong to Contingent Resources and the U labels to Prospective Resources. No zero-valued P labels are returned.'),
  ('prms', 'beginner', 'module', 'm02-discovered-and-undiscovered', 11, 'Ekene Deep, EKN-6, states a chance of geologic discovery of 25.000000 percent and a chance of development of 80.000000 percent. What chance of commerciality does the engine return?', '["25.000000 percent, Pg alone.", "80.000000 percent, Pd alone.", "10.500000 percent, the figure the engine returns for every Prospective project in the Ekene file.", "20.000000 percent, the product Pg x Pd."]'::jsonb, 3, 'For an undiscovered project Pc = Pg x Pd (PRMS 2.1.3.3), and the engine''s own decision line reads Pc = Pg x Pd = 25% x 80% = 20%. Either chance on its own leaves out the other judgement. 10.500000 percent is the chance of EKN-7, the lead, from its own stated chances.'),
  ('prms', 'beginner', 'module', 'm02-discovered-and-undiscovered', 12, 'Multiply out the stated chances of Ekene Shallow, the lead (Pg 15.000000, Pd 70.000000 percent). Which figure does the classification calculator print in its Chance of commerciality tile?', '["15.000000 percent.", "70.000000 percent.", "10.500000 percent.", "5.000000 percent."]'::jsonb, 2, 'The engine multiplies the two stated chances: 15.000000 percent times 70.000000 percent is 10.500000 percent. Neither chance alone is the chance of commerciality of an undiscovered project. 5.000000 percent is the chance of the play case, from its own stated Pg of 10.000000 and Pd of 50.000000 percent; the engine derives no chance from the sub-class.'),
  ('prms', 'beginner', 'module', 'm02-discovered-and-undiscovered', 13, 'The golden input class-pg-zero states a prospect with a chance of geologic discovery of 0.000000 percent. What does the engine return?', '["A Pc of 0.000000 percent, with the class still Prospective Resources and the sub-class prospect.", "A refusal, since a chance of geologic discovery must be above 0 for any prospect to be classified.", "The class Undiscovered Unrecoverable, since a prospect with no chance of discovery cannot be recovered.", "A Pc equal to the stated chance of development, since the zero chance is set aside."]'::jsonb, 0, 'The engine reports the product, 0.000000 percent, and keeps the class the facts give: Prospective Resources, sub-class prospect. A class is set by discovery and the recovery project, and the chance is a separate stated figure beside it. A Pg of 0 is inside the accepted range from 0 to 100.'),
  ('prms', 'beginner', 'module', 'm02-discovered-and-undiscovered', 14, 'Someone types a chance of geologic discovery of 50 into the box of Ekene North appraisal, which is discovered. Which message is printed?', '["chances must be left out for Reserves (PRMS 2.1.3.3 treats Reserves as near-certain to be commercial, so no chance figure is carried); got {\"developmentPct\":50}", "A result with the class changed to Prospective Resources, since only a prospect carries that chance.", "chances.developmentPct must be a number from 0 to 100; got nothing", "chances.geologicDiscoveryPct must be left out for a discovered accumulation (the chance of geologic discovery applies to Prospective Resources, PRMS 2.1.3.2); got 50"]'::jsonb, 3, 'Those are the engine''s own words. A discovered project has already been found, so its only chance is the chance of development, and Pc = Pd. The Reserves message applies to a project whose facts give Reserves, and EKN-4 is Contingent Resources. The engine multiplies nothing for a discovered project, and EKN-4 still states its chance of development.'),
  ('prms', 'beginner', 'module', 'm02-discovered-and-undiscovered', 15, 'What does the chance of commerciality of a prospect do to its 1U, 2U and 3U?', '["It multiplies them, so the engine returns each category already risked by the chance.", "Nothing: they stay the quantities the project would recover if it succeeds.", "It moves them into the 1C, 2C and 3C once the chance reaches 50 percent.", "The low estimate becomes the chance times the best estimate, as the 1U is defined."]'::jsonb, 1, 'The chance says how likely the project is to reach Reserves, and it sits beside the categories without changing them. A figure multiplied by a named chance is a risked figure, and the classification calculator returns none; the Expert tier takes that question up. No chance threshold moves quantities between classes, and each estimate is stated.'),
  ('prms', 'beginner', 'module', 'm03-reserves-and-contingent-resources', 1, 'When does the engine classify a discovered project with a recovery project as Reserves?', '["When at least five of the seven criteria are met and the economic status is stated \"viable\".", "Once its chance of development is above 50 percent.", "When all seven commerciality criteria and the firm intention are met with established technology.", "When the licensee has declared a commercial discovery to the Commission under the Petroleum Industry Act 2021."]'::jsonb, 2, 'The test is all or nothing (PRMS 2.1.2.1, Table 1): one criterion not met keeps the project in Contingent Resources, and the engine names every one that fails. A chance of development is stated beside a Contingent class and sets no class. A Nigerian declaration is printed as a note beside the class and leaves the PRMS class unchanged.'),
  ('prms', 'beginner', 'module', 'm03-reserves-and-contingent-resources', 2, 'Which criteria does the engine list as holding back EKN-4, Ekene North appraisal?', '["developmentPlan, financialAppropriations, approvals, firmIntention", "financialAppropriations, timeFrame, economicStatus, market, facilities, firmIntention", "technology under development, developmentPlan, financialAppropriations, economicStatus, firmIntention", "market, facilities"]'::jsonb, 0, 'The engine''s class decision on EKN-4 reads Contingent Resources: not commercial (developmentPlan, financialAppropriations, approvals, firmIntention). The six-name list is Ekene East gas, EKN-3, and the list that opens with technology under development is Ekene West tight sand, EKN-5. EKN-4 meets the market and facilities criteria.'),
  ('prms', 'beginner', 'module', 'm03-reserves-and-contingent-resources', 3, 'Ekene East gas, EKN-3, is held back by six criteria. Which two criteria does it meet?', '["market and facilities.", "timeFrame and economicStatus.", "financialAppropriations and firmIntention.", "developmentPlan and approvals."]'::jsonb, 3, 'The engine lists financialAppropriations, timeFrame, economicStatus, market, facilities and firmIntention as the blockers of EKN-3, so of the eight conditions the two it meets are the development plan and the approvals. Its market and facilities are among the blockers, and a significant gas discovery declaration is a Nigerian note printed beside the class.'),
  ('prms', 'beginner', 'module', 'm03-reserves-and-contingent-resources', 4, 'The golden case class-tech-under-development-only states every criterion met, with the recovery project stated as technology under development. What does the engine return?', '["Reserves, since every one of the eight commerciality conditions is met.", "Contingent Resources, with the one blocker \"technology under development\".", "A refusal naming `recoveryProject`, since a project that meets every criterion must state established technology to be accepted.", "Discovered Unrecoverable, since the recovery technology has not yet been shown to work in this field."]'::jsonb, 1, 'A project that relies on technology still under development cannot be Reserves even when every criterion is met, so the engine returns Contingent Resources and names technology under development as the blocker. It is a result, which the engine does not refuse. Discovered Unrecoverable needs a recovery project of none, and this one states a project.'),
  ('prms', 'beginner', 'module', 'm03-reserves-and-contingent-resources', 5, 'A learner states the economic status of a project as "positive". Which message does the engine print?', '["economicStatus must be one of \"viable\", \"not-viable\", \"undetermined\"; got \"positive\"", "commerciality.market must be true or false (stated; no default); got \"positive\"", "Criterion (4) read as met.", "economicStatus must be true or false (stated; no default); got \"positive\""]'::jsonb, 0, 'Those are the engine''s own words for the golden case class-refuse-economic-status. Positive economics is read from a stated economic status, and only the three named values are accepted. The economic status is stated as one of three words. The engine does not read an unaccepted word as met.'),
  ('prms', 'beginner', 'module', 'm03-reserves-and-contingent-resources', 6, 'What chance of commerciality does the engine return for Ekene East gas, EKN-3, a discovered project with a stated chance of development of 50.000000 percent?', '["25.000000 percent, a quarter point for each of the two criteria it meets.", "None: Contingent projects carry no chance.", "20.000000 percent, the figure of Ekene West tight sand, since both are held back by the economics criterion.", "50.000000 percent, since Pc = Pd for a discovered project."]'::jsonb, 3, 'For a discovered project the chance of commerciality is the chance of development alone (PRMS 2.1.3.3), and the engine prints Pc = Pd. The engine scores no criteria into a chance. A chance is carried by Contingent Resources and required for them; it is Reserves that carry none. EKN-5 states its own chance of development, 20.000000 percent.'),
  ('prms', 'beginner', 'module', 'm03-reserves-and-contingent-resources', 7, 'EKN-5 has five blockers and a chance of development of 20.000000 percent; EKN-3 has six blockers and 50.000000 percent. What explains the gap?', '["The engine lowers the chance by a fixed step for every blocker it finds on the project.", "The engine sets EKN-5 lower because technology under development counts as a double blocker.", "Each chance is a judgement the project team states, and the engine reports it beside the class.", "EKN-3 is gas, and the engine raises the chance of a gas project to allow for the significant discovery rules."]'::jsonb, 2, 'The chance of development is a stated input: the engine multiplies nothing and derives no chance from the number or kind of blockers. That is why the chances do not follow the count of blockers. The Nigerian note on EKN-3 is printed beside its class and changes no chance.'),
  ('prms', 'beginner', 'module', 'm03-reserves-and-contingent-resources', 8, 'What reserves status does the Ekene file state for EKN-2, Ekene infill wells, whose investment decision is taken and whose production is yet to start?', '["Developed-producing, since the decision is now taken.", "Undeveloped, since its production is yet to start.", "Developed-non-producing, since the wells wait on a pipeline.", "None, since a status is stated only with production."]'::jsonb, 1, 'EKN-2 is Reserves, sub-class approved-for-development, with a stated reserves status of undeveloped (PRMS 2.1.3.6, Table 2). Developed-producing needs a project on production, which EKN-2 is not. The Ekene file has no developed-non-producing project. Every Reserves project carries a stated status, producing or not.'),
  ('prms', 'beginner', 'module', 'm03-reserves-and-contingent-resources', 9, 'The Reserves status control on Ekene infill wells is set to developed-producing. Which message does the engine print?', '["subClass must be \"approved-for-development\" for this project (final investment decision taken; production yet to start: PRMS 2.1.3.5.5, Table 1); got \"developed-producing\"", "projectStatus.finalInvestmentDecision must be true for a project on production (a producing project has passed its investment decision); got false", "reservesStatus must be one of \"developed\", \"undeveloped\"; got \"developed-producing\"", "reservesStatus must be \"developed-non-producing\" or \"undeveloped\" for a project that is not on production (developed producing reserves come from completion intervals open and producing, Table 2); got \"developed-producing\""]'::jsonb, 3, 'Those are the engine''s own words for the golden case class-refuse-dp-not-producing: developed producing reserves need a project that is producing. The subClass message is about a stated sub-class, and the investment-decision message is about a producing project stated without its decision. The engine accepts three statuses, and the message names the two that fit this project.'),
  ('prms', 'beginner', 'module', 'm03-reserves-and-contingent-resources', 10, 'A box for a discovered project leaves out the market criterion inside `commerciality`. What happens?', '["commerciality.market must be true or false (stated; no default); got nothing", "The criterion is read as met.", "The criterion is read as not met, and market is added to the list of blockers.", "commerciality.markets is not an accepted key; the accepted keys of commerciality are developmentPlan, financialAppropriations, timeFrame, market, facilities, approvals, firmIntention"]'::jsonb, 0, 'Those are the engine''s own words. Every commerciality criterion is stated true or false with no default, so a missing one is refused by name and the engine does not guess it either way. The accepted-keys message answers a misspelt key such as markets, which is a different mistake.'),
  ('prms', 'beginner', 'module', 'm03-reserves-and-contingent-resources', 11, 'The years until development starts are stated as -1 in a project''s time-frame. Which message comes back?', '["A result with the time-frame met, since a start before now is sooner than any benchmark.", "commerciality.timeFrame must be true or false (stated; no default); got -1", "commerciality.timeFrame.startWithinYears must be a finite number at or above 0; got -1", "A result with timeFrame among the blockers."]'::jsonb, 2, 'Those are the engine''s own words for the golden case class-refuse-time-frame. The time-frame is read from a stated count of years until development starts, which may be zero and cannot be below it. It is one of the two criteria stated as something other than true or false, and a refused box returns no class, met or not.'),
  ('prms', 'beginner', 'module', 'm03-reserves-and-contingent-resources', 12, 'A Contingent Resources project is run with its whole `chances` object removed. What does the engine print?', '["chances must be left out for Reserves (PRMS 2.1.3.3 treats Reserves as near-certain to be commercial, so no chance figure is carried); got nothing", "chances must be an object { developmentPct } for Contingent Resources (PRMS 2.1.3.3: Pc = Pd); got nothing", "chances.developmentPct must be a number from 0 to 100; got nothing", "A result with no chance tile and the class Contingent Resources."]'::jsonb, 1, 'Those are the engine''s own words: a Contingent project requires its chance of development, since Pc = Pd, and the engine supplies none of its own. The Reserves message applies only when the facts give Reserves, and the developmentPct message answers an empty chances object that is still present. The engine fills no missing chance with a figure, and it returns no Contingent class without its chance.'),
  ('prms', 'beginner', 'module', 'm03-reserves-and-contingent-resources', 13, 'EKN-2 has its final investment decision and is not yet producing. A learner states its sub-class as development-pending. How does the engine respond?', '["It returns Contingent Resources, development-pending, since the stated sub-class decides the class.", "It accepts the stated sub-class and prints \"development-pending (stated)\" in the decision table.", "It returns Reserves at justified-for-development, the nearest Reserves sub-class to the stated one.", "It refuses: the facts give Reserves at approved-for-development, and the message names that sub-class."]'::jsonb, 3, 'For Reserves the engine derives the sub-class from the investment decision and production and checks the stated one against it. In its own words: subClass must be "approved-for-development" for this project (final investment decision taken; production yet to start: PRMS 2.1.3.5.5, Table 1); got "development-pending". The class comes from the criteria, and justified-for-development is the sub-class before the decision.'),
  ('prms', 'beginner', 'module', 'm03-reserves-and-contingent-resources', 14, 'Which section does the engine cite in the class decision of EKN-5, Ekene West tight sand, and which blocker does that decision list first?', '["PRMS Table 1 (Contingent Resources guidelines), listing technology under development first.", "PRMS 2.1.2.1 and Table 1, listing developmentPlan first, just as for Ekene North appraisal.", "PRMS 2.1.3.5.6 and Table 1, listing economicStatus first, because the economics are stated not viable.", "PRMS 2.1.1.2, listing firmIntention first."]'::jsonb, 0, 'The engine''s decision on EKN-5 cites PRMS Table 1 (Contingent Resources guidelines) and reads Contingent Resources: not commercial (technology under development, developmentPlan, financialAppropriations, economicStatus, firmIntention). PRMS 2.1.2.1 and Table 1 is what the other Contingent and the Reserves projects cite; 2.1.3.5.6 is the sub-class decision, and 2.1.1.2 belongs to the unrecoverable classes.'),
  ('prms', 'beginner', 'module', 'm03-reserves-and-contingent-resources', 15, '17 CFR 229.1203(d), quoted from the eCFR version current at 2026-09-01, asks a registrant to explain proved undeveloped reserves left undeveloped for five years or more. What does the engine do with that rule?', '["It moves undeveloped Reserves into Contingent Resources once five years have passed since the investment decision.", "It refuses the undeveloped status on any Reserves project whose sub-class is approved-for-development.", "It applies no such clock: it reads the reserves status that is stated.", "It prints a warning on EKN-2, whose status is undeveloped, citing the SEC rule."]'::jsonb, 2, 'The quoted rule is a disclosure rule for US registrants, and the course quotes it as public text. The engine applies no such clock and reads only the status stated, so EKN-2 is Reserves, undeveloped, with no warning. Undeveloped is an accepted status for an approved project.'),
  ('prms', 'beginner', 'module', 'm04-categories-and-the-range', 1, 'Which labels does the engine give the low, best and high estimates of Contingent Resources?', '["1P, 2P and 3P.", "1C, 2C and 3C.", "1U, 2U and 3U.", "C1, C2 and C3."]'::jsonb, 1, 'Each class has its own letter (PRMS 2.2.2.2 to 2.2.2.4): P for Reserves, C for Contingent Resources and U for Prospective Resources, with the number counting up from the low estimate. C1, C2 and C3 are the incremental slices of Contingent Resources, which the engine returns beside the cumulative 1C, 2C and 3C.'),
  ('prms', 'beginner', 'module', 'm04-categories-and-the-range', 2, 'The Ekene Main Reserves are stated cumulatively as 8.890000, 16.650000 and 24.990000 MMbbl. What is the 2P, and which probability label does the engine print beside it?', '["8.890000 MMbbl, P90.", "7.760000 MMbbl, labelled P50, the part of the best estimate that lies above the 1P.", "24.990000 MMbbl, P10.", "16.650000 MMbbl, labelled P50."]'::jsonb, 3, 'The 2P is the best estimate, 16.650000 MMbbl, and the engine labels the best case P50. 8.890000 is the 1P, the low case labelled P90. 7.760000 is the Probable (P2) slice, which is an increment and carries no probability label of its own. 24.990000 is the 3P.'),
  ('prms', 'beginner', 'module', 'm04-categories-and-the-range', 3, 'What Probable (P2) does the engine return for the Ekene Main Reserves (1P 8.890000, 2P 16.650000, 3P 24.990000 MMbbl)?', '["7.760000 MMbbl, what the 2P adds to the 1P.", "16.650000 MMbbl, the 2P itself, since the word probable names the best estimate.", "8.340000 MMbbl, the gap between the 3P and the 2P.", "8.890000 MMbbl."]'::jsonb, 0, 'The engine''s increments are Proved (P1) 8.890000, Probable (P2) 7.760000 and Possible (P3) 8.340000 MMbbl: 16.650000 less 8.890000 is 7.760000. The 2P is the cumulative best estimate, which includes the Proved slice. 8.340000 is the Possible (P3), and 8.890000 is the Proved (P1).'),
  ('prms', 'beginner', 'module', 'm04-categories-and-the-range', 4, 'In the same Ekene Main set, which figure is the Possible (P3)?', '["24.990000 MMbbl.", "7.760000 MMbbl.", "8.340000 MMbbl.", "16.650000 MMbbl."]'::jsonb, 2, 'Possible (P3) is the top slice: take the 2P of 16.650000 from the 3P of 24.990000 and 8.340000 is left, the figure the increments table prints. The 3P itself is cumulative and holds all three slices. 7.760000 is the middle slice, and 16.650000 is the best estimate.'),
  ('prms', 'beginner', 'module', 'm04-categories-and-the-range', 5, 'The Ekene North estimates are stated incrementally as C1 3.000000, C2 1.500000 and C3 2.000000. What 3C does the engine return?', '["6.500000.", "2.000000.", "4.500000.", "1.500000."]'::jsonb, 0, 'The 3C is cumulative: C1 plus C2 plus C3, 3.000000 plus 1.500000 plus 2.000000, which is 6.500000, and the engine returns the same figure when the set is stated cumulatively. 2.000000 is the C3 slice and 4.500000 is the 2C.'),
  ('prms', 'beginner', 'module', 'm04-categories-and-the-range', 6, 'The Ekene North set is entered twice: once as slices and once as totals of 3.000000, 4.500000 and 6.500000. What does the engine return for the two calls?', '["Different categories, since the incremental call treats each slice as its own estimate.", "The same cumulative figures, but increments only for the call stated incrementally.", "The same 1C, 2C and 3C and the same C1, C2 and C3 from each.", "A refusal on the second call."]'::jsonb, 2, 'Whichever form is stated, the engine returns both: the golden inputs cat-contingent-incremental and cat-contingent-cumulative give 1C 3.000000, 2C 4.500000, 3C 6.500000 and C1 3.000000, C2 1.500000, C3 2.000000. Each call is independent, and nothing is refused.'),
  ('prms', 'beginner', 'module', 'm04-categories-and-the-range', 7, 'The case "Prospective Resources" states 12.000000, 30.000000 and 70.000000 MMbbl. What does the engine return for the increments?', '["U1, U2 and U3 slices, named after the undiscovered class, printed beside the 1U, 2U and 3U.", "A refusal, because Prospective Resources are not categorized until a well has been drilled.", "Probable (P2) and Possible (P3) slices, since the engine uses Reserves names for every class.", "None, with the reason: incremental: no terms are defined for Prospective Resources (PRMS 2.2.2.4)"]'::jsonb, 3, 'The framework defines no incremental names for Prospective Resources, so the engine returns the 1U, 2U and 3U with no slices and prints that reason in its own words. It invents no U1, U2 or U3. Prospective Resources are categorized; only unrecoverable quantities are not.'),
  ('prms', 'beginner', 'module', 'm04-categories-and-the-range', 8, 'A learner sets the method of the Prospective case to incremental. What does the engine answer, in its own words?', '["method must be one of \"cumulative\", \"incremental\"; got nothing", "method must be \"cumulative\" for Prospective Resources (PRMS 2.2.2.4 defines no incremental terms for them); got \"incremental\"", "A result with the incremental slices of the prospect under the labels U1, U2 and U3.", "estimates.low must be left out for the incremental method (state first, second and third); got 12"]'::jsonb, 1, 'Those are the engine''s own words for the golden case cat-refuse-prospective-incremental. The "got nothing" message answers a method left out, and the estimates.low message answers a low stated with the incremental method on a class that has slices. The engine invents no slices for a prospect.'),
  ('prms', 'beginner', 'module', 'm04-categories-and-the-range', 9, 'The box of the categories view states resourceClass "resources". What does the engine print?', '["A result with the labels 1R, 2R and 3R, one set for all quantities together in the field.", "resourceClass must be one of \"reserves\", \"contingent\", \"prospective\"; got \"resources\"", "resourceClass must be one of \"reserves\", \"contingent\"; got \"resources\"", "A result under the Reserves labels 1P, 2P and 3P."]'::jsonb, 1, 'Those are the engine''s own words: resources alone names all quantities together and is no class of its own, and the categories view accepts three classes. Unrecoverable quantities are not in the list because they have no categories. The two-class list leaves out Prospective Resources, which do carry categories.'),
  ('prms', 'beginner', 'module', 'm04-categories-and-the-range', 10, 'A set states a low of 10, a best of 8 and a high of 12. What does the engine return?', '["The same three figures, sorted into the order 8, 10 and 12 before the labels are applied.", "A result with a note that the best estimate lies below the low, and all three labels printed.", "A result with the Probable (P2) printed as a negative slice of the best less the low.", "A refusal: the estimates must be ordered low <= best <= high, and the message restates that the low is the P90."]'::jsonb, 3, 'The engine refuses in its own words: estimates must be ordered low <= best <= high (the P90 low estimate, the P50 best, the P10 high: P90 means a 90% probability the actual quantity meets or exceeds this value, per SPE PRMS.); got {"low":10,"best":8,"high":12}. It sorts nothing and returns no figures on a refused box.'),
  ('prms', 'beginner', 'module', 'm04-categories-and-the-range', 11, 'Three equal estimates of 2.000000 go into the categories view. Which output comes back?', '["The three categories at 2.000000, singleValue true, and a reason citing PRMS 2.2.1.3.", "A refusal, because the ordering rule needs the low below the best and the best below the high.", "One category, the 2P, since a single value describes the best estimate alone.", "The three categories with singleValue false."]'::jsonb, 0, 'Each sign of the ordering rule reads at or below, so equal estimates are accepted. The engine returns 1P, 2P and 3P at 2.000000 and adds, in its own words: the low, best and high estimates are equal: a single value may describe the expected result (PRMS 2.2.1.3). The flag reads true only when all three figures are exactly equal.'),
  ('prms', 'beginner', 'module', 'm04-categories-and-the-range', 12, 'What slices does the engine return for the case "One value for the range", with 2.000000 stated for each estimate?', '["Proved (P1), Probable (P2) and Possible (P3) of 2.000000 each, one for every estimate stated.", "No slices at all.", "Proved (P1) 2.000000, Probable (P2) 0.000000 and Possible (P3) 0.000000.", "Proved (P1) 0.000000, Probable (P2) 2.000000 and Possible (P3) 0.000000."]'::jsonb, 2, 'The Proved slice is the whole 1P, 2.000000, and each later slice is the gap to the next estimate, which is zero. The 2P and 3P still equal the 1P. Three slices of 2.000000 each would add to a 3P of 6. Slices are returned for Reserves whatever their size. A Probable slice of the whole figure would need a 1P of zero.'),
  ('prms', 'beginner', 'module', 'm04-categories-and-the-range', 13, 'A learner raises the high estimate of "One value for the range" by a small amount. What happens to the tile "One value for the range"?', '["It stays true, since the three figures still round to the same value in the reason lines.", "It stays true until the gap between the estimates reaches one percent of the best estimate.", "The engine refuses the box, since a single-value case may not be edited.", "It reads false: the engine treats three figures that differ at all as an ordinary range."]'::jsonb, 3, 'The flag is true only when the three stated figures are exactly equal. Any difference makes an ordinary range, the reason citing PRMS 2.2.1.3 disappears, and the Possible (P3) slice becomes the small amount added. The engine uses no percentage threshold, and the box is an ordinary input the learner may change.'),
  ('prms', 'beginner', 'module', 'm04-categories-and-the-range', 14, 'A unit of a single space is stated in the categories view. What does the engine print?', '["unit must be a non-empty string; got \" \"", "A result with no unit printed in the Unit tile.", "A result in MMbbl, the unit of the start.", "unit must be one of \"MMbbl\", \"MMboe\", \"tcf\"; got \" \""]'::jsonb, 0, 'Those are the engine''s own words for the golden case cat-refuse-unit. The unit is a stated input with no default, and a blank string is refused. The engine does not fill in a unit, and it holds no list of accepted units: any non-empty string is accepted.'),
  ('prms', 'beginner', 'module', 'm04-categories-and-the-range', 15, 'On the Prospective case (12.000000, 30.000000 and 70.000000 MMbbl) the Class control is switched to Contingent Resources. What changes in the result?', '["Nothing changes: the labels follow the method alone.", "The engine refuses, since a Prospective case cannot be restated as another class.", "The labels become 1C, 2C and 3C, and an increments table of C1, C2 and C3 appears.", "The labels become 1P, 2P and 3P, since Contingent figures borrow the Reserves names."]'::jsonb, 2, 'The labels follow the stated class (PRMS 2.2.2.2 to 2.2.2.4): the same three figures come back as 1C, 2C and 3C, and because Contingent Resources have slices the engine adds C1, C2 and C3. The categories view reads only the stated class, so it has nothing to refuse. The P labels belong to Reserves, and the P90, P50 and P10 beside each row stay as they were.'),
  ('prms', 'beginner', 'module', 'm05-the-low-estimate-and-probability', 1, 'Which sentence does the engine return with every categorize call, from the course''s shared percentile convention?', '["P90 means the value that 90% of outcomes fall below, per the ordinary percentile table.", "P90 means a 90% chance that the project reaches Reserves, per the chance of commerciality.", "P90 means a 90% probability the actual quantity meets or exceeds this value, per SPE PRMS.", "P90 means the estimate is within 90% of the final quantity, per the reporting rules."]'::jsonb, 2, 'The sentence comes from lib/conventions/percentile.js and is printed as a note under the tables of the categories view. It is an exceedance probability: the chance of meeting or exceeding the figure. Counting the outcomes that fall below is the ordinary percentile, which runs the other way. The chance of reaching Reserves is the chance of commerciality, a separate figure.'),
  ('prms', 'beginner', 'module', 'm05-the-low-estimate-and-probability', 2, 'What does the label P50 beside a best estimate mean when the method is probabilistic?', '["At least a 50 percent probability that the quantity recovered meets or exceeds the figure.", "That the project has an even chance of being approved, whatever the quantity turns out to be.", "That half of the stated estimates were made by a probabilistic method and half by scenarios.", "Exactly 50 percent, no more and no less, since the best estimate is always the median of the range."]'::jsonb, 0, 'Each outcome label is an exceedance probability with the words at least: P90 at least 90 percent, P50 at least 50 percent, P10 at least 10 percent. It says nothing about approval, which is the class and its chance. The words at least matter: the label is a floor for the probability, and the engine states it only when the method is probabilistic.'),
  ('prms', 'beginner', 'module', 'm05-the-low-estimate-and-probability', 3, 'Which of the three Ekene Main Reserves figures carries the label P90?', '["24.990000 MMbbl, the 3P.", "16.650000 MMbbl, the 2P.", "7.760000 MMbbl, the Probable (P2).", "8.890000 MMbbl, the 1P."]'::jsonb, 3, 'P90 is always the low estimate: the smallest figure is the one most likely to be met or exceeded, so it carries the largest probability number. The engine prints P90 beside the 1P of 8.890000, P50 beside the 2P and P10 beside the 3P. A slice such as the Probable (P2) carries no probability label.'),
  ('prms', 'beginner', 'module', 'm05-the-low-estimate-and-probability', 4, 'A newcomer reads P90 the way an ordinary statistics table does. Where do they put it, and what is wrong with that?', '["At the bottom of the range, which is right, since the ordinary 90th percentile and P90 agree.", "At the top of the range, since ninety percent of outcomes lie below it; in this course P90 is the low estimate.", "In the middle of the range, since a probability of 90 is close to a probability of 50 in a wide range.", "Outside the range, since an ordinary percentile needs more than three estimates to be read."]'::jsonb, 1, 'The ordinary 90th percentile counts from the bottom, so ninety percent of outcomes fall below it and it is a large figure. Petroleum reporting counts exceedance from the top, so the P90 is the figure met or exceeded with at least 90 percent probability, the low estimate. The course fixes this reading once in lib/conventions/percentile.js.'),
  ('prms', 'beginner', 'module', 'm05-the-low-estimate-and-probability', 5, 'Why does every category line the engine prints add the words "when probabilistic"?', '["The engine runs a Monte Carlo on every category set and prints the words when it has sampled it.", "The engine cannot tell which method produced the figures, so it states the probability for the probabilistic case only.", "The words mark figures the engine will refuse if the method control is set to deterministic.", "It is a legal disclaimer required by 17 CFR 210.4-10(a)(24) on every figure that reaches a report."]'::jsonb, 1, 'The engine takes three estimates however they were made, so it states the probability conditionally. For a deterministic set, P90 is an outcome label for the low scenario. The engine''s categorize function samples nothing, its method input is cumulative or incremental, and the words come from the engine''s own convention, which no legal rule imposes.'),
  ('prms', 'beginner', 'module', 'm05-the-low-estimate-and-probability', 6, 'How are the low, best and high estimates made by a deterministic method?', '["As three points read off one distribution of outcomes, at the 90, 50 and 10 percent exceedance levels.", "As one scenario, with the low and high set at a fixed share of the best by the engine.", "As a distribution that the engine builds from the best estimate and the stated unit.", "As three scenarios, each worked out on its own set of inputs, with no distribution drawn."]'::jsonb, 3, 'A deterministic method picks a set of inputs for the low case, another for the best and another for the high, and works each out. Reading three points off a distribution is the probabilistic method. The engine builds no distribution and sets no estimate from another; every estimate is stated.'),
  ('prms', 'beginner', 'module', 'm05-the-low-estimate-and-probability', 7, 'In a deterministic estimate, what does the label P90 on the low scenario mean in this course?', '["A computed 90 percent probability, since the engine works it out from the spread of the three stated scenarios.", "Nothing at all: a deterministic set is refused unless it is relabelled low, middle and high.", "It is the outcome label of the low case; the low scenario is chosen to carry a high degree of confidence.", "That nine in ten of the scenarios the engineer tried came out above the low estimate."]'::jsonb, 2, 'For a deterministic set the engine does not claim a 90 percent chance. P90 stays attached as the outcome label of the low case, and the course reads the low scenario as one chosen to carry a high degree of confidence (PRMS 2.2.1.2 and 2.2.1.4, in the course''s words). The engine computes no probability from scenarios and refuses no deterministic set.'),
  ('prms', 'beginner', 'module', 'm05-the-low-estimate-and-probability', 8, 'How does 17 CFR 210.4-10(a)(24), from the eCFR version current at 2026-09-01, put the probability for proved reserves estimated by probabilistic methods?', '["At least a 90% chance that the quantities recovered reach or exceed the estimate.", "At least a 10% probability that the quantities recovered will exceed the estimate.", "Exactly 90% of the quantities in the ground, measured by a stated recovery factor.", "A 90% probability that the estimate lies within 10% of the final quantity recovered."]'::jsonb, 0, 'The public text reads: "If probabilistic methods are used, there should be at least a 90% probability that the quantities actually recovered will equal or exceed the estimate." (17 CFR 210.4-10(a)(24)). It states the exceedance idea in public words for US registrants. The 10 percent figure belongs to the high estimate. The rule sets no recovery factor and no closeness band.'),
  ('prms', 'beginner', 'module', 'm05-the-low-estimate-and-probability', 9, 'Why would it be wrong to say that the Probable (P2) of 7.760000 MMbbl has a 50 percent probability?', '["It would be right: the P2 slice carries the P50 label as the engine prints it in the table.", "The slice carries the P10 label, since it sits above the Proved slice.", "The Probable slice is a Contingent quantity, which carries a chance of development.", "A slice is the gap between two estimates and has no exceedance probability of its own."]'::jsonb, 3, 'Only the cumulative figures, the 1P, 2P and 3P, are estimates of the whole quantity and carry P90, P50 and P10. 7.760000 is what the 2P adds to the 1P, so no probability attaches to it. The increments table prints each slice with its label and value only. The Probable slice belongs to Reserves.'),
  ('prms', 'beginner', 'module', 'm05-the-low-estimate-and-probability', 10, 'Someone clears the method of the Ekene Main Reserves case and runs the categories view. What happens?', '["method must be \"cumulative\" for Prospective Resources (PRMS 2.2.2.4 defines no incremental terms for them); got nothing", "A refusal naming `method`: the method has no default, so a set with none stated is not read.", "A result read as cumulative, since low, best and high keys are present in the box.", "estimates must be ordered low <= best <= high; got nothing"]'::jsonb, 1, 'The engine''s own words are: method must be one of "cumulative", "incremental"; got nothing. It does not infer the method from the keys present. The Prospective message applies to an incremental method stated for Prospective Resources, and the ordering message to estimates out of order.'),
  ('prms', 'beginner', 'module', 'm05-the-low-estimate-and-probability', 11, 'A category set is stated with the cumulative method. Which figures are the learner''s, and which does the engine derive?', '["The slices are stated and the 1P, 2P and 3P derived.", "All six are stated; the engine checks that they add up and returns them unchanged.", "The 1P, 2P and 3P are stated; the engine derives the slices.", "The engine derives all six from the stated best estimate, the unit and the stated class."]'::jsonb, 2, 'With the cumulative method the low, best and high are stated and the engine works out Proved (P1), Probable (P2) and Possible (P3). With the incremental method it is the other way round. A mixed box is refused, and no estimate is derived from a single figure.'),
  ('prms', 'beginner', 'module', 'm05-the-low-estimate-and-probability', 12, 'The engine''s reason line prints the 1P of the Ekene Main Reserves as 8.89 MMbbl, and the table prints 8.890000. Which should a learner reason with?', '["The table figure at six decimals; the reason line drops trailing zeros.", "The reason line, since it is the engine''s own working and the table is rounded.", "Either, since the reason line and the table come from two separate calls.", "Neither: recompute it by hand."]'::jsonb, 0, 'Inside a reason the engine drops trailing zeros, so 8.890000 prints as 8.89. The table prints every quantity to six decimals, and that is the figure to reason and report with. Both come from the same call and agree; the table is the complete form.'),
  ('prms', 'beginner', 'module', 'm05-the-low-estimate-and-probability', 13, 'A report shows a 1P beside a Probable (P2). What goes wrong if the 2P is added to the Probable (P2)?', '["Nothing: the two can be added.", "The Proved slice is counted twice and the Probable slice is left out of the total.", "The engine refuses the sum, since categorize adds cumulative figures to slices on request.", "The Proved slice is counted once and the Probable slice twice."]'::jsonb, 3, 'The 2P already contains the Proved (P1) and the Probable (P2), so adding the Probable slice again counts it twice. Read each figure with its label and turn it into one form before adding or comparing. The categorize function adds nothing across forms on request; it returns both forms of one stated set.'),
  ('prms', 'beginner', 'module', 'm05-the-low-estimate-and-probability', 14, 'Which four fields does each cumulative row the engine returns carry?', '["The class, the unit, the method and the value, one row for each estimate.", "The case, the label, the probability label and the value.", "The label, the value, the slice and the chance of commerciality of the project.", "The case, the value, the section and the date."]'::jsonb, 1, 'Each cumulative row carries case, label, probability and value, for example low, 1P, P90, 8.890000. The class, the unit and the method are printed once as tiles. The slices sit in their own table, and the chance of commerciality belongs to the classification view. The engine records no estimate date.'),
  ('prms', 'beginner', 'module', 'm05-the-low-estimate-and-probability', 15, 'A 2U of 30.000000 MMbbl is read from the categories table of the Prospective case. What does that table leave unsaid?', '["How likely the project is to go ahead: that is the class and its chance of commerciality.", "The unit of the figure, since the Prospective case states no unit.", "The probability label of the figure, since Prospective Resources carry no P50.", "Whether the figure is the best estimate, since a 2U can sit anywhere in the range."]'::jsonb, 0, 'A category table answers the question about the estimate; the class and the chance of commerciality, in the classification view, answer the question about the project. The 2U of 30.000000 is the best estimate if the prospect succeeds. The case states its unit, MMbbl, and the 2U carries the P50 label like any best estimate.'),
  ('prms', 'beginner', 'module', 'm06-nigerian-terms-in-words', 1, 'Under s.78(8) of the Petroleum Industry Act 2021 (Official Gazette No. 142, Vol. 108, 27 August 2021), what must a licensee do once the appraisal programme is complete?', '["Submit a field development plan within 90 days, whatever the outcome of the appraisal.", "Report the discovery''s 1P, 2P and 3P to the Commission under the Act''s reserves booking rule.", "Relinquish the area unless a commercial discovery is declared on the day the appraisal ends.", "Declare a commercial discovery, declare a significant gas or crude oil discovery, or tell the Commission the discovery is of no interest."]'::jsonb, 3, 'Section 78(8) gives the three declarations: (a) a commercial discovery, (b) a significant gas or crude oil discovery, or (c) informing the Commission of no interest. A field development plan follows a commercial discovery within two years (s.79(1)); 90 days is the Commission''s approval of a significant discovery notice under reg. 6(2). No gazetted booking rule was found, and relinquishment follows the end of a retention period.'),
  ('prms', 'beginner', 'module', 'm06-nigerian-terms-in-words', 2, 'After a licensee declares a commercial discovery, within what period does s.79(1) of the Petroleum Industry Act 2021 require a field development plan?', '["Within 60 days of the declaration.", "Within two years of the declaration.", "Within 10 years of the declaration date.", "Within five years of the declaration."]'::jsonb, 1, 'The quoted text reads: "licensee shall within two years of the declaration, submit to the Commission a" (PIA s.79(1)). Sixty days is the notice of a significant discovery under reg. 5(1) of S.I. No. 37 of 2023, 10 years is the retention cap of s.78(9), and the five-year benchmark is a PRMS figure for the time-frame criterion.'),
  ('prms', 'beginner', 'module', 'm06-nigerian-terms-in-words', 3, 'For how long at most may a licensee retain the area of a significant discovery under s.78(9) of the Petroleum Industry Act 2021?', '["Not more than 10 years from the day the declaration was made.", "Not more than 8 years in deep water and 5 years onshore and in shallow water.", "For as long as the Commission decides, since the Act sets no upper limit.", "Two years, after which a field development plan must be submitted."]'::jsonb, 0, 'The Act caps retention: "which shall not be more than 10 years from the day the declaration was made" (PIA s.78(9)). The 5 and 8 years are the minimum approval periods of reg. 6(3) of S.I. No. 37 of 2023, and the Commission may grant up to the Act''s maximum. Two years is the field development plan period after a commercial discovery.'),
  ('prms', 'beginner', 'module', 'm06-nigerian-terms-in-words', 4, 'What does reg. 6(3) of the Significant Crude Oil and Gas Discovery Regulations, 2023 (S.I. No. 37 of 2023) set for an approval of retention?', '["A maximum of five years onshore and eight years offshore, after which the area is relinquished.", "A fixed ten years for every terrain, counted from the approval.", "A minimum of five years onshore and in shallow water, and eight years in deep water.", "A minimum of 90 days, the period the Commission has to approve a notice."]'::jsonb, 2, 'The regulation reads: "(3) An approval pursuant to subregulation (2) of this regulation shall be for a minimum period of five years in the onshore and shallow water areas, and eight years in the deep-water areas," and the Commission may grant up to the maximum the Act prescribes. The 10 years is that maximum in s.78(9), and the 90 days is the approval period of reg. 6(2).'),
  ('prms', 'beginner', 'module', 'm06-nigerian-terms-in-words', 5, 'Within how many days of completing the appraisal programme must a significant discovery be notified to the Commission, and how long does the Commission have to approve it?', '["90 days to notify and 60 days to approve, both under reg. 6.", "60 days to notify and two years to approve, under s.79(1) of the Act.", "60 days to notify (reg. 5(1)) and 90 days to approve (reg. 6(2)).", "Two years to notify and 10 years to approve, under s.78(9) of the Act."]'::jsonb, 2, 'S.I. No. 37 of 2023 sets the notice within 60 days after the appraisal programme (reg. 5(1)) and the Commission''s approval within 90 days of the notice (reg. 6(2)). Two years is the field development plan period of s.79(1), and 10 years the retention cap of s.78(9).'),
  ('prms', 'beginner', 'module', 'm06-nigerian-terms-in-words', 6, 'The case "A significant discovery eleven years on" states a significant crude oil discovery declared 11 years ago. What does the engine''s Nigerian note add that the note at 10 years does not?', '["That the area may be retained for up to 10 more years if the licensee asks the Commission in writing before the period ends.", "That the class changes to Discovered Unrecoverable, since the area has been given up and no project can now recover it.", "Nothing: both notes read the same, since the engine counts no years.", "That the retention period has ended, so the area is relinquished unless a commercial discovery was declared (s.78(13))."]'::jsonb, 3, 'In the engine''s own words the note at 11 years ends: 11 years since the declaration: the retention period has ended, so the area is relinquished unless a commercial discovery was declared (s.78(13)). At 10 years the note carries no such warning, since the tenth year is inside the period. The class stays Contingent Resources, because a note never changes the PRMS class.'),
  ('prms', 'beginner', 'module', 'm06-nigerian-terms-in-words', 7, 'EKN-1, which meets every commerciality criterion, is stated with a significant gas discovery declaration. What does the engine answer?', '["A refusal naming nigeria.declaration: a significant discovery cannot be declared commercial (PIA 2021 s.318).", "Contingent Resources, since a significant discovery is not yet commercial under the Act, and the declaration outweighs the criteria.", "Reserves, with a note that the significant declaration is out of date and should be replaced by a commercial one.", "Reserves with no note, since the Nigerian block is dropped when it contradicts the class."]'::jsonb, 0, 'The engine''s own words are: nigeria.declaration must be "commercial-discovery" for a project that meets every commerciality criterion: a significant discovery cannot be declared commercial (PIA 2021 s.318) and a discovery of no interest is not being developed (s.78(8)(c)); got "significant-gas-discovery". The notes do not change the class, so the contradiction is refused. Nothing in the box is dropped silently.'),
  ('prms', 'beginner', 'module', 'm06-nigerian-terms-in-words', 8, 'A learner adds the `nigeria` block {"declaration":"commercial-discovery","yearsSinceDeclaration":0} to EKN-6, the Ekene Deep prospect. Which message comes back?', '["nigeria.declaration must be one of \"commercial-discovery\", \"significant-crude-oil-discovery\", \"significant-gas-discovery\", \"no-interest\"; got \"commercial-discovery\"", "nigeria must be left out for an undiscovered accumulation (PIA 2021 s.78(8) declarations follow a discovery); got {\"declaration\":\"commercial-discovery\",\"yearsSinceDeclaration\":0}", "A result with the class Reserves, since a declared commercial discovery passes the commerciality test.", "A result with Prospective Resources and a note that a field development plan is due within 2 years."]'::jsonb, 1, 'Those are the engine''s own words for the golden case class-refuse-nigeria-undiscovered: the declarations of s.78(8) follow an appraisal, and a prospect has not been discovered. The message listing the four accepted declarations answers a declaration outside them, and commercial-discovery is one of them. A declaration sets no class.'),
  ('prms', 'beginner', 'module', 'm06-nigerian-terms-in-words', 9, 'What does the engine answer when the Nigerian declaration is stated as "significant"?', '["A note for a significant gas discovery, the one the engine assumes when the kind is not given.", "nigeria.declaration must be one of \"commercial-discovery\", \"significant-crude-oil-discovery\", \"significant-gas-discovery\", \"no-interest\"; got \"significant\"", "nigeria.declaration must be \"commercial-discovery\" for a project that meets every commerciality criterion; got \"significant\"", "A note for a significant crude oil discovery, since oil is the first kind the Act names."]'::jsonb, 1, 'Those are the engine''s own words for the golden case class-refuse-nigeria-declaration: the declaration must be one of the four accepted declarations, and the short form names neither kind of significant discovery. The engine assumes no kind. The commerciality message answers a significant declaration on a project that meets every criterion.'),
  ('prms', 'beginner', 'module', 'm06-nigerian-terms-in-words', 10, 'How does a Nigerian note change the PRMS class the engine returns?', '["A commercial discovery note raises a Contingent project to Reserves.", "A significant discovery note lowers a project to Contingent Resources whatever its criteria.", "Any no-interest note turns the project into Undiscovered Unrecoverable.", "It does not: the note is printed beside the class, which comes from the stated facts."]'::jsonb, 3, 'The Act''s declaration is a legal step with the regulator, and the PRMS class describes the project''s maturity; the engine carries the first as a note and leaves the second to the facts. Where the two contradict, as a significant declaration on a project meeting every criterion, the engine refuses. The no-interest case is discovered, and its class is Discovered Unrecoverable because its recovery project is none.'),
  ('prms', 'beginner', 'module', 'm06-nigerian-terms-in-words', 11, 'What does s.78(15) of the Petroleum Industry Act 2021 allow the Commission to do after a licensee declares a discovery of no interest?', '["Grant a retention period of at least five years before any relinquishment.", "Declare the discovery commercial on the licensee''s behalf and require a field development plan.", "Require relinquishment of the parcels that cover the structure of the discovery.", "Reclassify the quantities as Reserves in the national position."]'::jsonb, 2, 'The quoted text reads: "(15) Where a licensee declares a discovery of no interest under subsection (3) or (8), the Commission may require the relinquishment of the parcels that cover the structure of such discovery." (PIA s.78(15)). Retention follows a significant discovery. The Commission makes no commercial declaration for a licensee, and no Commission classification rule was read.'),
  ('prms', 'beginner', 'module', 'm06-nigerian-terms-in-words', 12, 'The Commission''s release of 1 April 2026 gives Nigeria''s 2P gas as at 1 January 2026. What total do its associated and non-associated figures make, and how does the course use the release?', '["215.19 trillion cubic feet (100.21 plus 114.98), cited for its figures and its date only.", "215.19 trillion cubic feet, quoted word for word with its citation, since a government release is public.", "114.98 trillion cubic feet, the non-associated figure alone, since associated gas is not counted.", "100.21 trillion cubic feet, the 1P gas, cited with the date the course read the release."]'::jsonb, 0, 'The release prints 2P associated gas of 100.21 and non-associated gas of 114.98 trillion cubic feet, 215.19 in total. Its page reads all rights reserved, so the course cites the figures and the date only. Both kinds of gas are in the total, and every figure in it is 2P. In this course the figure is reported reserves, with its date and the Commission as reporter.'),
  ('prms', 'beginner', 'module', 'm06-nigerian-terms-in-words', 13, 'What did the course find when it looked for a gazetted NUPRC regulation on how reserves are booked or reported?', '["The Commercial Regulations, 2025, which set the Nigerian booking rule the engine applies to each class.", "None on the Commission''s list read on 2026-09-27, so the course states no Nigerian booking rule.", "S.I. No. 37 of 2023, whose regulation 7 is the booking rule for a significant discovery.", "The 1 April 2026 release, which the Commission uses as its booking guideline."]'::jsonb, 1, 'No gazetted regulation or guideline on booking or reporting reserves was on the list read on 2026-09-27, so the course teaches the PRMS classes and states no Nigerian booking rule. The Commercial Regulations, 2025 ask for a status report and are used by concept only. Regulation 7 of S.I. No. 37 of 2023 covers a declaration that does not meet the criteria, and the release is a statement of figures.'),
  ('prms', 'beginner', 'module', 'm06-nigerian-terms-in-words', 14, 'What does s.7(i) of the Petroleum Industry Act 2021 give the Commission among its functions?', '["The classification of each licensee''s projects into the PRMS classes.", "The approval of every licensee''s 1P before it is reported to shareholders.", "The setting of a national price deck for the economic test of every project in the country.", "The evaluation of national reserves and policies for prudent reservoir management."]'::jsonb, 3, 'The quoted text reads: "(i) undertake evaluation of national reserves and develop policies for prudent reservoir management practices ;" (PIA s.7(i)). The quoted function concerns national reserves and reservoir management. None of the texts the course read gives the Commission the classification of each project, the approval of a company''s 1P or a national price deck.'),
  ('prms', 'beginner', 'module', 'm06-nigerian-terms-in-words', 15, 'A learner rehearses the capstone''s method on the Ekene field. Which pair of figures is the chance of commerciality of the prospect and of the lead?', '["20.000000 and 10.500000 percent, Ekene Deep and Ekene Shallow.", "25.000000 and 15.000000 percent, the chances of geologic discovery of the two.", "80.000000 and 70.000000 percent, the chances of development of the two.", "20.000000 and 20.000000 percent, since Ekene Deep and Ekene West share a figure."]'::jsonb, 0, 'Each is the product of the stated chances: 25.000000 percent times 80.000000 percent for Ekene Deep, and 15.000000 percent times 70.000000 percent for Ekene Shallow. The chances of geologic discovery or of development alone are one factor each. Ekene West tight sand, EKN-5, is a discovered Contingent project whose 20.000000 percent is its chance of development, and it is no lead.'),
  ('prms', 'beginner', 'final', null, 1, 'Which of the engine''s functions takes three stated estimates with a class, a method and a unit, and returns the categories?', '["`classify`.", "`aggregate`.", "`categorize`.", "`reconcile`."]'::jsonb, 2, 'categorize returns the cumulative categories with their outcome labels, the increments, the exceedance sentence and whether one value describes the range. classify returns the class, the sub-class and the category labels only, with no figures. aggregate and reconcile work on several projects or on movements, which belong to the Expert tier.'),
  ('prms', 'beginner', 'final', null, 2, 'What did the course find when it checked the consolidated PRMS errata (versions 1.01 to 1.03, May 2022)?', '["A change that adds the two chances together.", "A change that renames the 3P for Reserves only.", "A withdrawal of the 2018 text by the errata.", "No change to the sections the engine applies."]'::jsonb, 3, 'The errata were checked and change none of the sections the engine applies; they are cited by item and their prose is not quoted. Pc remains the product of Pg and Pd for a prospect, the labels are unchanged, and the course cites SPE-PRMS 2018 by section.'),
  ('prms', 'beginner', 'final', null, 3, 'From which document did the course read the English text of SPE-PRMS 2018?', '["A paid 2022 edition of the standard bought from SPE, since the 2018 text is out of print.", "The Commission''s copy attached to the Petroleum Industry Act 2021 as a schedule.", "A summary written by the course, since the licensed text was not read.", "The SPE-hosted English-Chinese edition, whose English is the 2018 text and whose section numbers are the 2018 numbers."]'::jsonb, 3, 'The sources table records the English text as read from the SPE-hosted English-Chinese edition (Version 2023 V1.0, developed from PRMS 2018 V1.0). It is the paid 2022 Application Guidelines that were not read, and the Act carries no copy of the standard.'),
  ('prms', 'beginner', 'final', null, 4, 'Who operates the synthetic Ekene field in the course''s fixture?', '["EKO, Ekene Operator (synthetic).", "The Commission, for the Federation.", "A real operator hidden behind a code.", "No operator; the fixture names none."]'::jsonb, 0, 'The fixture names EKO, Ekene Operator (synthetic), with a working interest of 70.000000 percent, on the Ekene petroleum mining lease (synthetic). Every name and figure in it is synthetic, and no real company appears. The working interest returns in the Professional tier.'),
  ('prms', 'beginner', 'final', null, 5, 'A box for EKN-1 carries the misspelt key `markets` inside `commerciality`. What does the engine print?', '["commerciality.markets is not an accepted key; the accepted keys of commerciality are developmentPlan, financialAppropriations, timeFrame, market, facilities, approvals, firmIntention", "commerciality.market must be true or false (stated; no default); got nothing", "A result with the class Reserves, since the misspelt key is set aside and the true market is assumed.", "maturity is not an accepted key; the accepted keys at the top level are name, discovery, recoveryProject, subClass, commerciality, economicStatus, projectStatus, reservesStatus, chances, nigeria"]'::jsonb, 0, 'Those are the engine''s own words for the golden case class-refuse-unknown-key. The accepted keys are checked before any input is read, so the unknown key is named first, with its path and the full list of keys the block does read. A misspelt key is refused. The maturity message answers an unknown key at the top level.'),
  ('prms', 'beginner', 'final', null, 6, 'Ekene Deep, EKN-6, also appears in another course of the academy. What is the link?', '["It is the discovery the pia course taxes, stated there as Reserves at on-production.", "It is the field the decline curve analysis course forecasts, stated there as developed-producing.", "It is the same prospect the farm-out course prices, with the same chance of geologic discovery.", "It is a different prospect that shares the name, with a different chance."]'::jsonb, 2, 'Ekene Deep is the prospect the farm-out course trades, carrying the same chance of geologic discovery. Here it is classified, as Prospective Resources with sub-class prospect. A prospect is undiscovered, so no course states it as Reserves or as developed-producing.'),
  ('prms', 'beginner', 'final', null, 7, 'Where do the practicals of this course run?', '["In the Suite app for reserves reporting, opened from the course page.", "In a spreadsheet the learner builds from the lesson tables and uploads with the answers at the end.", "In the course''s own calculator panels, which call the same vendored engine the lessons quote.", "In the Commission''s online reserves portal, which applies the PRMS classes."]'::jsonb, 2, 'This is an engine course with no Suite app. The Associate tier uses the classification calculator, and the later tiers add the reserves and aggregation calculators, each calling the same vendored engine on the learner''s own inputs. No regulator portal is part of the course.'),
  ('prms', 'beginner', 'final', null, 8, 'Which two Ekene projects are stated as undiscovered?', '["EKN-8 and EKN-5.", "EKN-3 and EKN-4.", "EKN-6 and EKN-7.", "EKN-1 and EKN-2, since both are named after the Ekene Main accumulation."]'::jsonb, 2, 'Ekene Deep (EKN-6) and Ekene Shallow (EKN-7) are potential accumulations still to be drilled, and the engine classifies both as Prospective Resources. The other six are discovered, including EKN-8, whose residual oil is known and has no recovery project.'),
  ('prms', 'beginner', 'final', null, 9, 'Ekene Deep''s chance of development is cleared in the panel before the call runs. Which refusal comes back?', '["A chance of commerciality of 25.000000 percent, the chance of geologic discovery alone.", "chances must be left out for Reserves (PRMS 2.1.3.3 treats Reserves as near-certain to be commercial, so no chance figure is carried); got nothing", "chances.geologicDiscoveryPct must be left out for a discovered accumulation; got nothing", "chances.developmentPct must be a number from 0 to 100; got nothing"]'::jsonb, 3, 'Those are the engine''s own words: a prospect needs both stated chances, and a missing one is refused by name. The engine multiplies nothing until both are stated. EKN-6 is Prospective Resources, and the Reserves and discovered-accumulation messages apply to other classes.'),
  ('prms', 'beginner', 'final', null, 10, 'The course''s small case "A play" states a Pg of 10.000000 percent and a Pd of 50.000000 percent. What chance of commerciality does the engine print?', '["10.000000 percent.", "5.000000 percent.", "50.000000 percent.", "20.000000 percent."]'::jsonb, 1, 'The play follows the same rule as the prospect and the lead (PRMS 2.1.3.3): Pg times Pd, whatever the sub-class, so 10.000000 percent times 50.000000 percent gives 5.000000 percent. Taking one stated chance on its own drops a judgement, and 20.000000 percent belongs to Ekene Deep''s own chances.'),
  ('prms', 'beginner', 'final', null, 11, 'The decision table for EKN-6 reads "prospect (stated)" in its sub-class row. What does the word "stated" signal?', '["The engine derived the sub-class from the chances, and \"stated\" marks a figure it computed from the two stated chances.", "The Commission has approved the sub-class, and \"stated\" is the regulator''s mark.", "The sub-class is provisional and will be replaced once a well is drilled on the prospect.", "The engine took the sub-class from the input and checked only that it is one of the three Prospective ones."]'::jsonb, 3, 'For Contingent and Prospective Resources the engine takes the stated sub-class and checks it belongs to the class (PRMS 2.1.3.5.9, Table 1 for a prospect). It derives no sub-class from the chances; only a Reserves sub-class is derived from stated facts. No regulator approval is involved.'),
  ('prms', 'beginner', 'final', null, 12, 'Part of the residual oil in Ekene Main becomes reachable by a new recovery method. How does the engine deal with it?', '["It moves that part out of Discovered Unrecoverable on its own, once the method has been named in the file.", "Nothing: the part stays Discovered Unrecoverable for good, since a class once given cannot change.", "It refuses any new project on EKN-8, since unrecoverable quantities take no recovery project.", "That part is stated again with its new project and classified afresh; the engine keeps no memory of an earlier class."]'::jsonb, 3, 'A class is a statement about today''s facts. When a project can reach part of the residual oil, that part is stated with the project and classified again, and every call reads only the facts in its box. The engine moves nothing by itself and holds no history. A recovery project is a stated input on any discovered quantity.'),
  ('prms', 'beginner', 'final', null, 13, 'The course''s case "A discovery of no interest" states a discovered project with no recovery project and a no-interest declaration. What does the engine return?', '["Contingent Resources at development-not-viable, with the declaration as its only blocker.", "A refusal on the no-interest declaration.", "Undiscovered Unrecoverable, since a discovery of no interest is treated as never found.", "Discovered Unrecoverable, with a note citing s.78(8)(c) and s.78(15) of the Act."]'::jsonb, 3, 'The class comes from the facts, discovered with no recovery project, and the engine''s note reads, in its own words: discovery declared of no interest (PIA 2021 s.78(8)(c)); the Commission may require relinquishment of the parcels over the structure (s.78(15)). The note leaves the class unchanged.'),
  ('prms', 'beginner', 'final', null, 14, 'Which reserves status does the Ekene file state for EKN-1, the waterflood on production?', '["Undeveloped.", "Developed-producing.", "Developed-non-producing.", "No status at all."]'::jsonb, 1, 'The waterflood is on production, and its sub-class decision reads on-production: on production, selling petroleum to market. A developed-producing status needs exactly that, wells open and producing now. Injection wells still to drill and zones shut in behind pipe describe the other two statuses.'),
  ('prms', 'beginner', 'final', null, 15, 'Two of the eight commerciality conditions are read from inputs other than a plain true or false. Which two?', '["The market and the facilities.", "The approvals and the firm intention.", "The time-frame and the economic status.", "The development plan and the financial appropriations, which the engine reads from a budget."]'::jsonb, 2, 'The time-frame is read from a stated number of years until development starts, with a stated flag for a longer time-frame that is justified; positive economics is read from the stated economic status: viable, undetermined or not-viable. The other six are each stated true or false. The engine reads no budget.'),
  ('prms', 'beginner', 'final', null, 16, 'Which of the three Ekene Contingent projects states its economic status as viable?', '["EKN-3, Ekene East gas.", "EKN-5, Ekene West tight sand.", "None of the three.", "EKN-4, Ekene North appraisal."]'::jsonb, 3, 'EKN-4 is stated viable and is held back by its plan, money, approvals and firm intention. EKN-3 is undetermined and EKN-5 not-viable, which is why economicStatus is among their blockers. Viable economics is one criterion of eight, so a viable project can still be Contingent Resources.'),
  ('prms', 'beginner', 'final', null, 17, 'Why does the chance column read none for EKN-1 and EKN-2?', '["They are Reserves, which carry no chance figure (PRMS 2.1.3.3).", "Their chances were left out of the file by mistake and should be filled in.", "Their chance is kept in a separate Reserves file that the table does not read.", "They are on production."]'::jsonb, 0, 'Reserves are treated as near-certain to be commercial, so no chance figure is carried, and stating one is refused. EKN-2 is not on production and still carries none. The engine prints no chance of 100 percent for Reserves; it prints none.'),
  ('prms', 'beginner', 'final', null, 18, 'A discovered project meets all seven commerciality criteria with established technology, but its firm intention to proceed is stated false. Which class does the engine return?', '["Contingent Resources, held back by firmIntention.", "Reserves, whatever the intention.", "Reserves at justified-for-development, the sub-class for a project still waiting on its commitment.", "A refusal naming firmIntention, since a project meeting seven criteria must state it true."]'::jsonb, 0, 'The firm intention is part of the test (PRMS 2.1.2.1, 2.1.2.3), and the test is all or nothing, so the engine returns Contingent Resources and names firmIntention as the one blocker. A false criterion is a stated fact; the engine does not refuse it. Justified-for-development is a Reserves sub-class, which needs every condition met.'),
  ('prms', 'beginner', 'final', null, 19, 'A box states a project on production whose final investment decision is stated false. What does the engine answer?', '["reservesStatus must be \"developed-non-producing\" or \"undeveloped\" for a project that is not on production; got false", "projectStatus.finalInvestmentDecision must be true for a project on production (a producing project has passed its investment decision); got false", "A result with the sub-class on-production and a warning that the decision date is missing.", "A result with the sub-class justified-for-development, since no decision has been taken."]'::jsonb, 1, 'The engine''s own words name the field projectStatus.finalInvestmentDecision (golden case class-refuse-producing-without-fid). Production can only follow an investment decision, so the pair of stated facts cannot both hold. The reservesStatus message concerns a producing status stated on an idle project, and a refused box brings back no sub-class or warning.'),
  ('prms', 'beginner', 'final', null, 20, 'A learner adds a project status block to EKN-4, Ekene North appraisal. Why is it refused?', '["EKN-4 is undiscovered, and a project status block is read only for projects whose accumulation has been discovered.", "The project status sets a Reserves sub-class, so it must be left out for Contingent Resources (PRMS 2.1.3.5).", "The block names the wrong keys; the engine accepts only finalInvestmentDecision.", "A project status can be stated only together with a Nigerian declaration."]'::jsonb, 1, 'The engine refuses the block by name: projectStatus must be left out for Contingent Resources, since the investment decision and production are the facts that set a Reserves sub-class. EKN-4 is discovered. The project status block has two keys, finalInvestmentDecision and onProduction, and has nothing to do with a Nigerian note.'),
  ('prms', 'beginner', 'final', null, 21, 'Why do the Prospective Resources categories use the letter U?', '["The quantities are undiscovered: 1U, 2U and 3U belong to Prospective Resources.", "U stands for unrecoverable, the class that Prospective Resources fall into before a well.", "An unrisked figure is marked U, and only Prospective Resources carry one.", "U stands for uncertain, since only prospects have a range of outcomes."]'::jsonb, 0, 'The letter names the class: P for Reserves, C for Contingent Resources and U for the undiscovered quantities of Prospective Resources. Unrecoverable quantities carry no categories at all. Every class with a project has a range of outcomes.'),
  ('prms', 'beginner', 'final', null, 22, 'In the Ekene Main Reserves, how do the 1P and the Proved (P1) compare?', '["The Proved (P1) is 7.760000.", "16.650000 is the 1P, and the Proved (P1) is its first half.", "The Proved (P1) is 8.340000, the last of the three slices.", "They are the same figure, 8.890000 MMbbl: 1P = P1."]'::jsonb, 3, 'The Proved slice is the whole 1P, and the engine prints the rule in its own words: 1P = P1, 2P = P1 + P2, 3P = P1 + P2 + P3. 7.760000 is the Probable (P2), and 16.650000 is the 2P. No slice is taken off the 1P.'),
  ('prms', 'beginner', 'final', null, 23, 'A set is stated incrementally with a second slice of -1. What does the engine print?', '["A result with a 2P below the 1P and a warning line in the reasons.", "A refusal naming estimates.second, since a slice may be zero and may not fall below it.", "estimates must be ordered low <= best <= high; got -1", "estimates.second must be left out for the cumulative method (state low, best and high); got -1"]'::jsonb, 1, 'In the engine''s own words (golden case cat-refuse-negative-increment): estimates.second must be a finite number at or above 0; got -1. A slice may be zero or above. The ordering message answers cumulative figures out of order, and the mixed-forms message answers a slice key under the cumulative method. A refused box returns no categories.'),
  ('prms', 'beginner', 'final', null, 24, 'Under the incremental method, a Reserves box keeps a leftover `low` of 1 from its cumulative form. Which message comes back?', '["estimates.low must be left out for the incremental method (state first, second and third); got 1", "A result that treats the low as the Proved (P1) and ignores the first slice.", "estimates.second must be a finite number at or above 0; got 1", "method must be \"cumulative\" for Prospective Resources (PRMS 2.2.2.4 defines no incremental terms for them); got \"incremental\""]'::jsonb, 0, 'Those are the engine''s own words for the golden case cat-refuse-incremental-with-low: each method reads its own three keys, and a cumulative key under the incremental method is refused. The engine sets no stated input aside. The Prospective message applies only to Prospective Resources.'),
  ('prms', 'beginner', 'final', null, 25, 'Ekene North is stated as totals of 3.000000, 4.500000 and 6.500000. Which figure is both its 1C and its C1?', '["1.500000, the C2.", "4.500000, the 2C, which is the first figure a report quotes for Contingent Resources.", "3.000000.", "6.500000."]'::jsonb, 2, 'The first slice of any class is the whole low estimate: the 1C is C1, 3.000000, as the engine returns for both golden inputs. 1.500000 is the C2 slice, 4.500000 the 2C, and 6.500000 the 3C.'),
  ('prms', 'beginner', 'final', null, 26, 'A report adds a 2P, a 2C and a 2U into one figure. What does that figure describe?', '["The field''s 2P, since Contingent and Prospective figures become Reserves once added.", "No class and no project: the labels keep each class apart, and figures of different classes stay out of one total.", "The field''s best estimate of all resources, which is how the framework defines a total.", "A risked best estimate, since the Prospective figure carries its chance into the sum."]'::jsonb, 1, 'Each class carries its own labels so that a figure is never mistaken for another class. Added together, a 2P, a 2C and a 2U belong to no class and describe no project. Adding changes no class, and a risked figure is one multiplied by a named chance, which no plain sum applies.'),
  ('prms', 'beginner', 'final', null, 27, 'Which figure does the engine return as the 3U of the course''s Prospective case, and which probability label sits beside it?', '["12.000000 MMbbl, labelled P90.", "70.000000 MMbbl, labelled P10.", "30.000000 MMbbl, labelled P50, the best estimate if the prospect succeeds.", "70.000000 MMbbl, labelled P90, since the prospect has the widest range of the three classes."]'::jsonb, 1, 'The case states 12.000000, 30.000000 and 70.000000 MMbbl, and the engine returns them as 1U, 2U and 3U with P90, P50 and P10 beside them. The 3U is the high estimate, so it carries P10 in every class. 12.000000 is the 1U and 30.000000 the 2U.'),
  ('prms', 'beginner', 'final', null, 28, 'Which probability label does the engine print beside the 1C of Ekene North?', '["C90, since the probability label takes the class letter.", "P10, since Contingent Resources count their probabilities from the bottom.", "P90, the label of every low estimate whatever its class.", "None: probability labels are printed for Reserves only."]'::jsonb, 2, 'The outcome labels are the same in every class: P90 beside the low, P50 beside the best and P10 beside the high. The class letters, P, C and U, change with the class, and the outcome labels do not. The 1C of Ekene North and the 1U of the prospect case are both P90 figures within their own class.'),
  ('prms', 'beginner', 'final', null, 29, 'Picture a hundred equally likely outcomes for a Reserves estimate, sorted from smallest to largest. Where does the P10 sit?', '["Near the top: only ten or more of the outcomes reach it.", "Near the bottom, since ten percent of the outcomes fall below it.", "In the middle, with half of the outcomes above it.", "Below the P90, since a smaller number means a smaller figure."]'::jsonb, 0, 'The P10 is a figure met or exceeded by at least ten in a hundred outcomes, so it sits near the top of the sorted list; the P90, met or exceeded by at least ninety, sits near the bottom, and the P50 in the middle. Reading P10 from the bottom is the ordinary percentile, which runs the other way.'),
  ('prms', 'beginner', 'final', null, 30, 'Why does petroleum reporting count exceedance from the top when an ordinary statistics table counts from the bottom?', '["Because a Reserves estimate is always made by a deterministic method.", "Because the question a lender or a regulator asks is how much is at least there.", "Because the SEC rules forbid percentiles counted from the bottom in any filing.", "Because the engine sorts every estimate from largest to smallest before printing it."]'::jsonb, 1, 'Reporting asks how much is at least there, so the P90 is the figure met or exceeded with at least 90 percent probability, the low estimate. Estimates are made by either method. The quoted SEC text states the exceedance idea for proved reserves and forbids nothing about tables, and the engine sorts nothing: it refuses estimates out of order.'),
  ('prms', 'beginner', 'final', null, 31, 'In the course''s fixed order for reading a category table, which item comes first, and why?', '["The value of the 2P, since the best estimate is the figure most readers want.", "The reasons, since they state everything the table does in words.", "The class, since it tells the reader which labels to expect.", "The unit."]'::jsonb, 2, 'The order runs class, unit, method, labels and probabilities, increments, and last the reasons. The class comes first because it sets the letters: P for Reserves, C for Contingent Resources and U for Prospective Resources. A class a reader did not expect means the table is about a different project.'),
  ('prms', 'beginner', 'final', null, 32, 'Ekene North''s three slices are typed in as the incremental method asks. Who supplies which figures in the result?', '["The 1C, 2C and 3C are stated; the engine works out the slices.", "Only the C1 is stated; the engine extends it to the rest of the range.", "The C1, C2 and C3 are stated; the engine works out the 1C, 2C and 3C.", "All six are stated, and the engine checks that each slice matches the totals it was given."]'::jsonb, 2, 'With the incremental method the three slices are stated and the engine builds the cumulative figures from them: 3.000000, 1.500000 and 2.000000 give 3.000000, 4.500000 and 6.500000. With the cumulative method it is the other way round. A box stating both forms is refused.'),
  ('prms', 'beginner', 'final', null, 33, 'The engine cannot tell whether three estimates came from scenarios or from a distribution. What should a report do about it?', '["Write the method beside every category table, so a reader knows whether P90 is a probability or a label.", "Leave the method out, since the engine''s words \"when probabilistic\" already settle it.", "Relabel deterministic figures low, middle and high, since the P labels belong to distributions.", "Convert every deterministic set to a distribution before it is reported, using the engine."]'::jsonb, 0, 'The engine states the probability only for the probabilistic case, so the report has to say which method was used. The P labels stay attached in both cases as outcome labels, and the engine builds no distribution from scenarios.'),
  ('prms', 'beginner', 'final', null, 34, 'Which of the Ekene Main Reserves figures carries at least a 10 percent probability of being met or exceeded, when the method is probabilistic?', '["8.890000 MMbbl, the 1P.", "8.340000 MMbbl, the Possible (P3), which is the slice at the high end of the range.", "24.990000 MMbbl, the 3P.", "16.650000 MMbbl, the 2P, since ten percent is the step between two categories."]'::jsonb, 2, 'The high estimate carries P10: at least a 10 percent probability of being met or exceeded, so it is the 3P of 24.990000. The 1P carries P90 and the 2P P50. A slice such as the Possible (P3) is not an estimate of the whole quantity and carries no probability.'),
  ('prms', 'beginner', 'final', null, 35, 'How does s.318 of the Petroleum Industry Act 2021 define a commercial discovery, in the course''s words?', '["One whose 2P has been booked by the Commission under its reserves regulation.", "One the licensee judges can be economically developed after weighing all relevant economic factors.", "One with a field development plan approved within two years of the declaration.", "One whose chance of development is stated at or above the threshold the Commission publishes each year."]'::jsonb, 1, 'Section 318 defines a commercial discovery as one that can be economically developed in the opinion of the licensee or lessee after consideration of all relevant economic factors. No Commission booking regulation was found. The field development plan follows the declaration under s.79(1), and the Act sets no chance threshold.'),
  ('prms', 'beginner', 'final', null, 36, 'Which Nigerian note does the engine print for EKN-3, Ekene East gas?', '["A commercial discovery under s.78(8)(a), with a field development plan due within 2 years.", "A discovery of no interest under s.78(8)(c), with relinquishment of the parcels over the structure.", "No note, since a Contingent Resources project carries no Nigerian declaration.", "A significant gas discovery under s.78(8)(b), with the retention rules and 3 years since the declaration."]'::jsonb, 3, 'EKN-3 is stated as a significant gas discovery declared 3 years ago, and the engine''s note cites s.78(8)(b), s.318, s.78(9) and reg. 6(3) and ends 3 years since the declaration. The commercial discovery note is EKN-1''s. A discovered Contingent project may carry a note, and the note leaves its class unchanged.'),
  ('prms', 'beginner', 'final', null, 37, 'Which two reasons in s.318 of the Petroleum Industry Act 2021 for a significant gas discovery concern markets?', '["No markets for natural gas within Nigeria, and export markets that still need to be identified and developed.", "A royalty rate too high for the gas to pay, and a tax rate above the one in the pia course.", "No field development plan within two years, and no approval from the Commission within 90 days.", "A gas price below the domestic base price, and a pipeline more than 10 years from completion."]'::jsonb, 0, 'The Act lists them as (a) no markets for natural gas within Nigeria and (b) export markets need to be identified and developed, and reg. 4(a) and (b) of S.I. No. 37 of 2023 repeat them. The Act''s definition names no royalty, tax, price or pipeline test, and the two years and 90 days belong to other provisions.'),
  ('prms', 'beginner', 'final', null, 38, 'Under reg. 7(2) of S.I. No. 37 of 2023, what happens when a licensee whose declaration does not meet the criteria says it intends to declare a commercial discovery?', '["The Commission grants two years to submit a field development plan under section 79 of the Act.", "The Commission grants a retention period of at least five years onshore.", "The area is relinquished at once under s.78(13) of the Act.", "The Commission declares the discovery commercial and books its 2P in the national figure."]'::jsonb, 0, 'The regulation reads: "(2) Where the licensee informs the Commission that it intends to declare a commercial discovery, the Commission shall grant the licensee two years within which to submit a field development plan for the area in accordance with section 79 of the Act." Retention periods follow an approved significant discovery, relinquishment under s.78(13) follows the end of retention, and no booking rule was read.'),
  ('prms', 'beginner', 'final', null, 39, 'What does reg. 7(3) of S.I. No. 37 of 2023 require when the licensee says the discovery is of no interest?', '["The Commission grants the licensee two years to change its mind before the parcels are released.", "The Commission requires relinquishment of the parcels that cover the structure, pursuant to s.78(15) of the Act.", "The licensee pays a penalty set by the Commission and keeps the parcels.", "The discovery is reclassified as Prospective Resources and offered in the next licensing round."]'::jsonb, 1, 'The regulation reads that the Commission shall, pursuant to s.78(15), require the licensee to relinquish the parcels that cover the structure of such discovery from its licence area. The two-year grant is reg. 7(2), for a licensee that intends a commercial declaration. The texts read set no penalty, and a discovered quantity is never Prospective Resources.'),
  ('prms', 'beginner', 'final', null, 40, 'The engine''s Nigerian note on EKN-1 ends "12 years since the declaration: the two-year period has passed". What does that note do to the class?', '["It lowers EKN-1 to Contingent Resources until a late field development plan is filed.", "Nothing: EKN-1 stays Reserves, and the note is printed beside the class.", "It turns EKN-1 into Discovered Unrecoverable, since the plan period has lapsed.", "A refusal comes back, since the years since the declaration are above two."]'::jsonb, 1, 'The notes do not change the PRMS class: EKN-1 meets every criterion and is Reserves, and the note reports that the two-year plan period of s.79(1) has passed. The engine accepts any stated count of years at or above 0 and prints what the Act provides beside the class.'),
  ('prms', 'beginner', 'final', null, 41, 'How does the course use the Nigerian Upstream Petroleum (Commercial) Regulations, 2025 (S.I. No. 7 of 2025)?', '["As the Nigerian booking rule, which the engine applies to set each class.", "As a quoted text, since Nigerian subsidiary legislation may be quoted with its citation.", "It is the source of the national gas figures as at 1 January 2026.", "By concept only: reg. 6 asks for a status report that includes a statement of the reserves situation."]'::jsonb, 3, 'The Commercial Regulations are used by concept only, for the status report of reg. 6. No gazetted booking rule was found, so the engine applies none. The national gas figures come from the Commission''s release of 1 April 2026.'),
  ('prms', 'beginner', 'final', null, 42, 'In which gazette was S.I. No. 37 of 2023 published, and when was it made?', '["Official Gazette No. 111, Vol. 110, 20 June 2023, made 24 May 2023.", "Official Gazette No. 142, Vol. 108, 27 August 2021, made with the Act.", "Official Gazette No. 84, Vol. 112, 5 May 2025, made with the Commercial Regulations.", "Official Gazette No. 110, Vol. 111, 24 May 2023, made 20 June 2023."]'::jsonb, 0, 'The sources table gives S.I. No. 37 of 2023, Official Gazette No. 111, Vol. 110, 20 June 2023 (made 24 May 2023). Gazette No. 142, Vol. 108 of 27 August 2021 carries the Act, and Gazette No. 84, Vol. 112 of 5 May 2025 the Commercial Regulations. Swapping the numbers and dates names no real gazette.');
